/* ── favorites / channel defaults / profiles ───────────────────────────── */

export const getVoiceFavorites = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }): Promise<{ characterIds: string[] }> => {
    const client = asVoiceIntelClient(context.supabase);
    const { data, error } = await client
      .from("user_voice_favorites")
      .select("character_id")
      .eq("user_id", context.userId)
      .order("created_at", { ascending: false });
    if (error) {
      // Migration not applied yet → no favorites possible.
      if (isMissingTableError(error)) return { characterIds: [] };
      throw new Error(error.message);
    }
    return { characterIds: (data ?? []).map((r) => r.character_id) };
  });

export const toggleVoiceFavorite = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(CharacterIdSchema)
  .handler(async ({ data, context }): Promise<{ favorited: boolean }> => {
    if (!voiceCharacter(data.characterId)) {
      throw new Error("That voice doesn't exist.");
    }
    const client = asVoiceIntelClient(context.supabase);
    const { data: existing, error: readError } = await client
      .from("user_voice_favorites")
      .select("character_id")
      .eq("user_id", context.userId)
      .eq("character_id", data.characterId)
      .maybeSingle();
    assertNoDbError(readError, "Voice favorites aren't available yet — try again shortly.");
    if (existing) {
      const { error } = await client
        .from("user_voice_favorites")
        .delete()
        .eq("user_id", context.userId)
        .eq("character_id", data.characterId);
      assertNoDbError(error, "Voice favorites aren't available yet — try again shortly.");
      return { favorited: false };
    }
    const { error } = await client
      .from("user_voice_favorites")
      .insert({ user_id: context.userId, character_id: data.characterId });
    assertNoDbError(error, "Voice favorites aren't available yet — try again shortly.");
    return { favorited: true };
  });

export const getChannelVoiceDefault = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .inputValidator(ChannelDefaultGetSchema)
  .handler(async ({ data, context }): Promise<{ selection: VoiceSelection | null }> => {
    const client = asVoiceIntelClient(context.supabase);
    const { data: row, error } = await client
      .from("channel_voice_defaults")
      .select("selection")
      .eq("user_id", context.userId)
      .eq("scope", data.scope)
      .maybeSingle();
    if (error) {
      if (isMissingTableError(error)) return { selection: null };
      throw new Error(error.message);
    }
    return { selection: row?.selection ?? null };
  });

export const saveChannelVoiceDefault = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(ChannelDefaultSaveSchema)
  .handler(async ({ data, context }): Promise<{ ok: true }> => {
    const client = asVoiceIntelClient(context.supabase);
    const { error } = await client.from("channel_voice_defaults").upsert(
      { user_id: context.userId, scope: data.scope, selection: data.selection },
      { onConflict: "user_id,scope" },
    );
    assertNoDbError(error, "Channel voice defaults aren't available yet — try again shortly.");
    return { ok: true };
  });

export const listVoiceProfiles = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .handler(async ({ context }): Promise<{ profiles: VoiceProfile[] }> => {
    const client = asVoiceIntelClient(context.supabase);
    const { data, error } = await client
      .from("voice_profiles")
      .select("id, name, selection, created_at")
      .eq("user_id", context.userId)
      .order("created_at", { ascending: false });
    if (error) {
      if (isMissingTableError(error)) return { profiles: [] };
      throw new Error(error.message);
    }
    return {
      profiles: (data ?? []).map((r) => ({
        id: r.id,
        name: r.name,
        selection: r.selection,
        createdAt: r.created_at,
      })),
    };
  });

export const saveVoiceProfile = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(VoiceProfileSaveSchema)
  .handler(async ({ data, context }): Promise<{ profile: VoiceProfile }> => {
    const client = asVoiceIntelClient(context.supabase);
    const { data: row, error } = await client
      .from("voice_profiles")
      .insert({ user_id: context.userId, name: data.name.trim(), selection: data.selection })
      .select("id, name, selection, created_at")
      .single();
    assertNoDbError(error, "Voice profiles aren't available yet — try again shortly.");
    if (!row) throw new Error("Could not save the voice profile.");
    return {
      profile: { id: row.id, name: row.name, selection: row.selection, createdAt: row.created_at },
    };
  });

export const deleteVoiceProfile = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(VoiceProfileDeleteSchema)
  .handler(async ({ data, context }): Promise<{ ok: true }> => {
    const client = asVoiceIntelClient(context.supabase);
    const { error } = await client
      .from("voice_profiles")
      .delete()
      .eq("id", data.id)
      .eq("user_id", context.userId);
    assertNoDbError(error, "Voice profiles aren't available yet — try again shortly.");
    return { ok: true };
  });

/* ── project persistence / analytics ───────────────────────────────────── */

export const getProjectVoiceConfig = createServerFn({ method: "GET" })
  .middleware([requireSupabaseAuth])
  .inputValidator(ProjectVoiceConfigGetSchema)
  .handler(async ({ data, context }): Promise<{ selection: VoiceSelection | null }> => {
    const client = asVoiceIntelClient(context.supabase);
    const { data: project, error } = await client
      .from("projects")
      .select("id, voice_config")
      .eq("id", data.projectId)
      .eq("user_id", context.userId)
      .maybeSingle();
    if (error) throw new Error(error.message);
    if (!project) throw new Error("Project not found.");
    return { selection: project.voice_config ?? null };
  });

export const saveProjectVoiceConfig = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(ProjectVoiceConfigSaveSchema)
  .handler(async ({ data, context }): Promise<{ ok: true }> => {
    const client = asVoiceIntelClient(context.supabase);
    // Verify the project belongs to the caller before writing.
    const { data: project, error: readError } = await client
      .from("projects")
      .select("id")
      .eq("id", data.projectId)
      .eq("user_id", context.userId)
      .maybeSingle();
    if (readError) throw new Error(readError.message);
    if (!project) throw new Error("Project not found.");
    const { error } = await client
      .from("projects")
      .update({ voice_config: data.selection })
      .eq("id", data.projectId)
      .eq("user_id", context.userId);
    if (error) throw new Error(error.message);
    return { ok: true };
  });

export const trackVoiceEvent = createServerFn({ method: "POST" })
  .middleware([requireSupabaseAuth])
  .inputValidator(TrackVoiceEventSchema)
  .handler(async ({ data, context }): Promise<{ ok: true }> => {
    // Best-effort: analytics must never break the caller's flow.
    try {
      await asVoiceIntelClient(context.supabase)
        .from("voice_analytics_events")
        .insert({
          user_id: context.userId,
          event: data.event,
          metadata: data.metadata ?? {},
        });
    } catch {
      // Never throw — a failed analytics write is invisible to the user.
    }
    return { ok: true };
  });

export type { VoiceSettings };
